// Ported from the Node app's Sequelize model BiometricPunch (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class BiometricPunchConfiguration : IEntityTypeConfiguration<BiometricPunch>
{
    public void Configure(EntityTypeBuilder<BiometricPunch> builder)
    {
        builder.ToTable("biometric_punches");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.DeviceId).HasColumnName("device_id");
        builder.Property(e => e.EnrollId).HasColumnName("enroll_id").HasColumnType("nvarchar(40)").HasMaxLength(40).IsRequired();
        builder.Property(e => e.StudentId).HasColumnName("student_id");
        builder.Property(e => e.PunchedAt).HasColumnName("punched_at").HasColumnType("datetime2");
        builder.HasIndex(e => new { e.DeviceId, e.EnrollId, e.PunchedAt }).IsUnique().HasDatabaseName("uq_punch");
        builder.HasIndex(e => e.PunchedAt).HasDatabaseName("ix_punch_time");
        builder.HasOne(e => e.BiometricDevice).WithMany(p => p.BiometricPunches).HasForeignKey(e => e.DeviceId).OnDelete(DeleteBehavior.NoAction);
        builder.HasOne(e => e.Student).WithMany(p => p.BiometricPunches).HasForeignKey(e => e.StudentId).OnDelete(DeleteBehavior.NoAction);
    }
}
